using ReeLib;using System.Text.Json;
Directory.SetCurrentDirectory("E:/CodexPepo/RE_Research");var parts=new List<object>();var wanted=new[]{"01","02","10","21","40","50"};
foreach(var file in Directory.GetFiles("reports/model/samples","*.mesh.*",SearchOption.AllDirectories).Concat(Directory.GetFiles("reports/model_extra/samples","*.mesh.*",SearchOption.AllDirectories).Where(p=>!p.Contains("streaming")))){if(!wanted.Any(id=>Path.GetFileName(file).StartsWith("ch0100_"+id+"_00")))continue;using var m=new MeshFile(new FileHandler(file));m.Read();var sf=file.Replace("reports/model/samples","reports/model_streaming/samples").Replace("stm\\character","stm\\streaming\\character");if(File.Exists(sf))m.LoadStreamingData(new FileHandler(sf));var bd=m.BoneData!;var deform=bd.DeformBones.Count>0?bd.DeformBones:bd.Bones;var used=new HashSet<int>();foreach(var g in m.MeshData!.LODs[2].MeshGroups)foreach(var sub in g.Submeshes){var material=m.MaterialNames[sub.materialIndex];if(material.Contains("EyeShell")||material.Contains("Eyelash")||material.Contains("Eyebrow")||material.Contains("Beard"))continue;foreach(var w in sub.Weights)for(int k=0;k<Math.Min(8,w.IndexCount);k++)if(w.GetWeight(k)>0)used.Add(deform[w.GetIndex(k)].index);}parts.Add(new{name=Path.GetFileName(file),bones=bd.Bones.Select(b=>new{name=b.name}).ToArray(),primitives=new[]{new{joints=used.ToArray(),weights=used.Select(_=>1).ToArray()}}});}
var clips=new List<object>();foreach(var e in JsonDocument.Parse(File.ReadAllText("reports/phase2/effective_files.json")).RootElement.EnumerateArray()){var path=e.GetProperty("Path").GetString()!;bool add=path.EndsWith("/ch0100_handgun00h_add.motlist.1047");if(!add&&!path.EndsWith("/ch0100_handgun00h.motlist.1047"))continue;using var f=new MotlistFile(new FileHandler(e.GetProperty("File").GetString()!));f.Read();var ent=f.Motions.First(x=>x.motNumber==(add?1200:160));var m=(MotFile)ent.MotFile!;clips.Add(new{id=ent.motNumber,additive=add,bones=m.Bones.Select(b=>new{name=b.boneName}).ToArray(),tracks=m.BoneClips.Select(c=>new{bone=m.Bones.FindIndex(b=>b.boneHash==c.ClipHeader.boneHash)}).ToArray()});}
File.WriteAllText("reports/phase2/bone_statistics_source.json",JsonSerializer.Serialize(new{model=new{parts},motion=new{clips}}));Console.WriteLine($"Read {parts.Count} model parts and {clips.Count} representative clips");
